using Ardalis.Result; using Mediator; using Microsoft.AspNetCore.Identity; using Nimble.Modulith.Users.Contracts;
namespace Nimble.Modulith.Users.UseCases;
public record CreateUserInternalCommand(string Email,string Password):ICommand<Result<string>>;
public class CreateUserInternalCommandHandler(UserManager<IdentityUser> userManager):ICommandHandler<CreateUserInternalCommand,Result<string>>{ public async ValueTask<Result<string>> Handle(CreateUserInternalCommand c,CancellationToken ct){ var existing=await userManager.FindByEmailAsync(c.Email); if(existing is not null) return Result<string>.Success(existing.Id); var user=new IdentityUser{UserName=c.Email,Email=c.Email,EmailConfirmed=true}; var r=await userManager.CreateAsync(user,c.Password); if(!r.Succeeded) return Result<string>.Error(string.Join("; ",r.Errors.Select(e=>e.Description))); await userManager.AddToRoleAsync(user,"User"); return Result<string>.Success(user.Id); } }
public class CreateUserCommandHandler(IMediator mediator):ICommandHandler<CreateUserCommand,Result<string>>{ public ValueTask<Result<string>> Handle(CreateUserCommand c,CancellationToken ct)=>mediator.Send(new CreateUserInternalCommand(c.Email,c.Password),ct); }
